#!/usr/bin/env python"""Comprehensive Test for AutoMLQSARRegressorTests all features of the new regression-focused AutoML QSAR module:- Data validation and noise detection- Outlier detection and management- Feature space exploration- Model family exploration- Hyperparameter optimization- Automated report generation"""import osimport sysimport warningsimport numpy as npimport pandas as pdwarnings.filterwarnings('ignore')# Add project to pathsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))def test_data_validator():    """Test the DataValidator component."""    print("\n" + "="*70)    print("TEST 1: DataValidator - SMILES Validation, Noise & Outlier Detection")    print("="*70)        from automl_qsar.pipeline.automl_regressor import DataValidator        validator = DataValidator()        # Test SMILES with some invalid ones    smiles = np.array([        "CC(=O)OC1=CC=CC=C1C(=O)O",  # Aspirin - valid        "INVALID_SMILES",             # Invalid        "CCO",                         # Ethanol - valid        "C1=CC=CC=C1",                 # Benzene - valid        "NOT_A_MOLECULE",              # Invalid        "CC(C)CC1=CC=C(C=C1)C(C)C(=O)O",  # Ibuprofen - valid    ])        # Values with outliers    values = np.array([1.5, 2.0, 1.8, 1.6, 2.2, 50.0])  # 50.0 is outlier        print("\nTesting SMILES validation...")    valid_mask, validation_info = validator.validate_smiles(smiles)    print(f"  Valid SMILES: {valid_mask.sum()}/{len(smiles)}")    print(f"  Validation info: {validation_info}")        # Filter to valid only    valid_smiles = smiles[valid_mask]    valid_values = values[valid_mask]        print(f"\nTesting outlier detection on {len(valid_values)} samples...")    outlier_mask, outlier_info = validator.detect_outliers(valid_values)    print(f"  Outliers detected: {outlier_mask.sum()}/{len(valid_values)}")    print(f"  Values: {valid_values}")    print(f"  Outlier mask: {outlier_mask}")        print("\n✓ DataValidator test completed!")    return Truedef test_feature_space_explorer():    """Test the FeatureSpaceExplorer component."""    print("\n" + "="*70)    print("TEST 2: FeatureSpaceExplorer - Descriptor & Fingerprint Exploration")    print("="*70)        from automl_qsar.pipeline.automl_regressor import FeatureSpaceExplorer        explorer = FeatureSpaceExplorer()        # Test molecules    smiles = np.array([        "CC(=O)OC1=CC=CC=C1C(=O)O",  # Aspirin        "CC(C)CC1=CC=C(C=C1)C(C)C(=O)O",  # Ibuprofen        "CN1C=NC2=C1C(=O)N(C(=O)N2C)C",  # Caffeine        "CC(=O)NC1=CC=C(C=C1)O",  # Paracetamol        "CCO",  # Ethanol        "CCCCC",  # Pentane        "C1=CC=CC=C1",  # Benzene        "CC(C)C",  # Isobutane    ])    y = np.array([3.5, 4.0, 2.1, 2.8, 0.5, 0.2, 1.2, 0.1])        print("\nExploring feature space...")    results = explorer.explore_feature_space(smiles, y)        print(f"\nConfigurations evaluated: {len(results['all_results'])}")    for config in results['all_results'][:5]:        print(f"  {config['featurizer']} + {config['preprocessing']}: RMSE = {config['rmse']:.4f}")        print(f"\nBest configuration: {results['best_configuration']['featurizer']} + {results['best_configuration']['preprocessing']}")        print("\n✓ FeatureSpaceExplorer test completed!")    return Truedef test_model_explorer():    """Test the ModelExplorer component."""    print("\n" + "="*70)    print("TEST 3: ModelExplorer - Multi-Model Family Exploration")    print("="*70)        from automl_qsar.pipeline.automl_regressor import ModelExplorer        explorer = ModelExplorer()        # Create synthetic regression data    np.random.seed(42)    n_samples = 50    X = np.random.randn(n_samples, 10)    y = 3 * X[:, 0] - 2 * X[:, 1] + X[:, 2] + np.random.randn(n_samples) * 0.5        print(f"\nExploring models on {n_samples} samples, {X.shape[1]} features...")    results = explorer.explore_models(X, y, cv_folds=3)        print(f"\nModels evaluated: {len(results['all_results'])}")    print("\nModel scores (RMSE):")        for result in results['all_results']:        print(f"  {result['model']} ({result['family']}): RMSE = {result['rmse']:.4f}")        print(f"\nBest model: {results['best_model']['model']}")        print("\n✓ ModelExplorer test completed!")    return Truedef test_hyperparameter_optimizer():    """Test the HyperparameterOptimizer component."""    print("\n" + "="*70)    print("TEST 4: HyperparameterOptimizer - Bayesian Optimization")    print("="*70)        from automl_qsar.pipeline.automl_regressor import HyperparameterOptimizer, ModelExplorer        optimizer = HyperparameterOptimizer(method='bayesian', n_trials=10)    model_explorer = ModelExplorer()        # Create synthetic data    np.random.seed(42)    n_samples = 50    X = np.random.randn(n_samples, 10)    y = 3 * X[:, 0] - 2 * X[:, 1] + X[:, 2] + np.random.randn(n_samples) * 0.5        print(f"\nOptimizing Random Forest on {n_samples} samples...")        # Get param space    param_space = model_explorer.get_hyperparameter_space('randomforest')        results = optimizer.optimize('randomforest', X, y, param_space, cv_folds=3)        print(f"\nBest parameters: {results['best_params']}")    print(f"Best CV RMSE: {results['best_score']:.4f}")        print("\n✓ HyperparameterOptimizer test completed!")    return Truedef test_full_pipeline():    """Test the complete AutoMLQSARRegressor pipeline."""    print("\n" + "="*70)    print("TEST 5: Full AutoMLQSARRegressor Pipeline with IC50 Dataset")    print("="*70)        from automl_qsar import AutoMLQSARRegressor        # Load IC50 dataset    df = pd.read_csv('kinase_ic50_dataset.csv')        # Convert IC50 to pIC50    df['pIC50'] = -np.log10(df['IC50_nM'].values * 1e-9)        print(f"\nDataset: {len(df)} compounds")    print(f"pIC50 range: {df['pIC50'].min():.2f} - {df['pIC50'].max():.2f}")        # Initialize regressor with reduced parameters for testing    regressor = AutoMLQSARRegressor(        featurizers=['rdkit', 'ecfp'],        models=['ridge', 'randomforest'],        n_trials=5,           # Reduced for quick testing        cv_folds=3,        random_state=42,        verbose=True    )        print("\nRunning AutoML pipeline...")        # Load data and fit    regressor.load_data(data=df, smiles_col='SMILES', target_col='pIC50')    results = regressor.fit()        print("\n" + "-"*50)    print("RESULTS SUMMARY")    print("-"*50)        if 'validation' in results:        val = results['validation']        print(f"\nData Validation:")        if 'smiles' in val:            print(f"  Valid molecules: {val['smiles']['valid']}/{val['smiles']['total']}")        if 'outliers' in val:            print(f"  Outliers detected: {val['outliers']['n_outliers']}")        if 'features' in results:        feat = results['features']        print(f"\nFeature Exploration:")        if 'best_configuration' in feat:            print(f"  Best featurizer: {feat['best_configuration']['featurizer']}")        if 'models' in results:        model = results['models']        print(f"\nModel Exploration:")        if 'best_model' in model:            print(f"  Best model: {model['best_model']['model']}")        if 'final_metrics' in results:        metrics = results['final_metrics']        print(f"\nFinal Model Metrics:")        print(f"  R²:   {metrics.get('r2', 'N/A'):.4f}")        print(f"  RMSE: {metrics.get('rmse', 'N/A'):.4f}")        print(f"  MAE:  {metrics.get('mae', 'N/A'):.4f}")        print(f"  Q²:   {metrics.get('q2', 'N/A'):.4f}")        # Test predictions    print("\nTesting predictions...")    test_smiles = df['SMILES'].tolist()[:5]    predictions = regressor.predict(test_smiles)    actual = df['pIC50'].values[:5]        print(f"  Sample predictions: {predictions.round(3)}")    print(f"  Actual values:      {actual.round(3)}")        print("\n✓ Full pipeline test completed!")    return Truedef test_report_generation():    """Test the automated report generation."""    print("\n" + "="*70)    print("TEST 6: ReportGenerator - Automated Report Generation")    print("="*70)        from automl_qsar.pipeline.automl_regressor import ReportGenerator        generator = ReportGenerator(output_dir='test_reports')        # Add mock sections    generator.add_section('summary', {        'n_samples': 40,        'n_features': 200,        'best_model': 'random_forest',        'best_rmse': 0.42,        'best_r2': 0.91    })        generator.add_section('validation', {        'smiles': {'total': 40, 'valid': 38, 'invalid': 2},        'outliers': {'n_outliers': 2, 'method': 'iqr'},        'duplicates': {'n_duplicates': 0}    })        generator.add_section('features', {        'best_configuration': {'featurizer': 'rdkit', 'preprocessing': 'standard'},        'all_results': [            {'featurizer': 'rdkit', 'preprocessing': 'standard', 'rmse': 0.42, 'n_features': 200},            {'featurizer': 'ecfp', 'preprocessing': 'minmax', 'rmse': 0.48, 'n_features': 2048}        ]    })        generator.add_section('models', {        'best_model': {'model': 'random_forest', 'family': 'tree'},        'all_results': [            {'model': 'random_forest', 'family': 'tree', 'rmse': 0.42, 'rmse_std': 0.05},            {'model': 'ridge', 'family': 'linear', 'rmse': 0.55, 'rmse_std': 0.08}        ]    })        generator.add_section('hpo', {        'method': 'bayesian',        'n_trials': 50,        'best_score': 0.38,        'best_params': {'n_estimators': 200, 'max_depth': 10}    })        generator.add_section('final_model', {        'rmse': 0.42,        'mae': 0.31,        'r2': 0.91,        'q2': 0.88    })        print("\nGenerating report...")    report_path = generator.save_report()    print(f"  Report saved to: {report_path}")        # Check files exist    import os    report_dir = 'test_reports'    if os.path.exists(os.path.join(report_dir, 'qsar_report.md')):        size = os.path.getsize(os.path.join(report_dir, 'qsar_report.md'))        print(f"  Markdown report size: {size} bytes")        if os.path.exists(os.path.join(report_dir, 'report_data.json')):        size = os.path.getsize(os.path.join(report_dir, 'report_data.json'))        print(f"  JSON report size: {size} bytes")        print("\n✓ ReportGenerator test completed!")    return Truedef main():    """Run all tests."""    print("\n" + "#"*70)    print("#  AutoMLQSARRegressor Comprehensive Test Suite")    print("#  Testing all features of the regression-focused AutoML QSAR module")    print("#"*70)        tests = [        ("DataValidator", test_data_validator),        ("FeatureSpaceExplorer", test_feature_space_explorer),        ("ModelExplorer", test_model_explorer),        ("HyperparameterOptimizer", test_hyperparameter_optimizer),        ("ReportGenerator", test_report_generation),        ("Full Pipeline", test_full_pipeline),    ]        results = []    for name, test_func in tests:        try:            success = test_func()            results.append((name, "PASSED" if success else "FAILED"))        except Exception as e:            print(f"\n✗ {name} test FAILED with error:")            print(f"  {type(e).__name__}: {str(e)}")            import traceback            traceback.print_exc()            results.append((name, f"ERROR: {str(e)[:50]}"))        # Print summary    print("\n" + "="*70)    print("TEST SUMMARY")    print("="*70)        passed = sum(1 for _, status in results if status == "PASSED")    total = len(results)        for name, status in results:        symbol = "✓" if status == "PASSED" else "✗"        print(f"  {symbol} {name}: {status}")        print(f"\nTotal: {passed}/{total} tests passed")        if passed == total:        print("\n🎉 All tests passed successfully!")        return 0    else:        print(f"\n⚠️  {total - passed} test(s) failed")        return 1if __name__ == "__main__":    sys.exit(main())